-- Additive curated catalog. Existing slugs and admin edits are preserved.
BEGIN;
INSERT INTO public.explore_resources (slug,kind,title,summary,cover_url,duration_minutes,tags,steps,body,featured_rank,published)
SELECT slug,kind,title,summary,cover_url,duration_minutes,tags,steps,body,featured_rank,published FROM jsonb_populate_recordset(NULL::public.explore_resources, '[{"slug":"push-day-preparation","title":"Before push day","summary":"Ease into pressing with shoulder movement and light practice.","cover_url":"https://images.unsplash.com/photo-1518611012118-696072aa579a?auto=format&fit=crop&w=1200&q=85","featured_rank":10,"published":true,"kind":"mobility","duration_minutes":5,"tags":["Shoulders","Warm-up"],"steps":[{"title":"Comfortable marching","seconds":90,"instruction":"Stand tall beside a wall. Lift one foot, set it down softly and alternate. Let your arms move naturally. Start slowly and increase your pace only while breathing comfortably.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793746/fitsync/exercises/explore-diagrams/rglkocnvdlksryqtwfan.webp","image_alt":"Illustrated movement cue: March in place. Alternate a comfortable knee lift.","modification":"Keep both hands on a stable chair and lift the feet just a few centimetres.","video_url":null},{"title":"Small shoulder circles","seconds":60,"instruction":"Stand or sit tall. With arms relaxed, circle the shoulders up, back and down for 30 seconds, then reverse. Keep the neck relaxed; make smooth circles without shrugging hard.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793748/fitsync/exercises/explore-diagrams/khlbksy8mbq6hobq51eg.webp","image_alt":"Illustrated movement cue: Shoulder circles. Small circles, relaxed neck.","modification":"Sit with feet on the floor and reduce the size of each circle.","video_url":null},{"title":"Wall slides","seconds":90,"instruction":"Stand with your back near a wall and elbows bent. Slide arms upward only as far as you can without arching the lower back. Lower slowly. Wall contact is optional; do not force wrists or elbows flat.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793749/fitsync/exercises/explore-diagrams/wpv11pbv5nimhxcwxz2u.webp","image_alt":"Illustrated movement cue: Wall slides. Ribs stacked, slide arms comfortably.","modification":"Slide one arm at a time, or stop below shoulder height.","video_url":null},{"title":"Seated upper-back turns","seconds":60,"instruction":"Sit toward the front of a stable chair, feet flat. Cross arms over your chest and gently turn your ribs to one side. Return to centre and alternate. Keep knees facing forward.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793749/fitsync/exercises/explore-diagrams/klxkmiaxxjmgepokqvz2.webp","image_alt":"Illustrated movement cue: Seated rotation. Turn the ribs; keep pelvis still.","modification":"Rest hands on thighs and use a smaller turn.","video_url":null}],"body":[]},{"slug":"squat-day-preparation","title":"Before squat day","summary":"Prepare ankles, hips and your squat pattern before loaded sets.","cover_url":"https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=1200&q=85","featured_rank":11,"published":true,"kind":"mobility","duration_minutes":6,"tags":["Lower body","Warm-up"],"steps":[{"title":"Comfortable marching","seconds":90,"instruction":"Stand tall beside a wall. Lift one foot, set it down softly and alternate. Let your arms move naturally. Start slowly and increase your pace only while breathing comfortably.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793746/fitsync/exercises/explore-diagrams/rglkocnvdlksryqtwfan.webp","image_alt":"Illustrated movement cue: March in place. Alternate a comfortable knee lift.","modification":"Keep both hands on a stable chair and lift the feet just a few centimetres.","video_url":null},{"title":"Supported ankle rocks","seconds":90,"instruction":"Face a wall in a short split stance. Keep the front heel planted and gently move the front knee forward over the toes, then back. Spend 45 seconds on each side without forcing depth.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793750/fitsync/exercises/explore-diagrams/qkksxgcc0ad7vptjzdru.webp","image_alt":"Illustrated movement cue: Ankle rock. Heel stays down, knee moves forward.","modification":"Move the front foot nearer the wall and reduce the forward shift.","video_url":null},{"title":"Wall hip hinges","seconds":90,"instruction":"Stand a short step in front of a wall, facing away. Soften knees, push hips back to lightly touch the wall, then stand tall. Keep your back long and pressure through the whole foot.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793751/fitsync/exercises/explore-diagrams/me1sh8gd8g7heyfskvlo.webp","image_alt":"Illustrated movement cue: Hip hinge. Send hips back, keep a long spine.","modification":"Stand closer to the wall and use a shorter range.","video_url":null},{"title":"Supported shallow squats","seconds":90,"instruction":"Hold a sturdy support. Place feet about shoulder-width apart. Bend hips and knees together into a comfortable shallow squat, then stand. Keep heels grounded and knees following the toes.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793752/fitsync/exercises/explore-diagrams/xe31ad2yvjy46lnwnh5i.webp","image_alt":"Illustrated movement cue: Supported squat. Sit back with stable support.","modification":"Use a high stable chair for slow sit-to-stands, with arm support as needed.","video_url":null}],"body":[]},{"slug":"hinge-day-preparation","title":"Before deadlift day","summary":"A simple standing preparation for hip hinges and pulling sessions.","cover_url":"https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=85","featured_rank":12,"published":true,"kind":"mobility","duration_minutes":6,"tags":["Hips","Warm-up"],"steps":[{"title":"Comfortable marching","seconds":90,"instruction":"Stand tall beside a wall. Lift one foot, set it down softly and alternate. Let your arms move naturally. Start slowly and increase your pace only while breathing comfortably.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793746/fitsync/exercises/explore-diagrams/rglkocnvdlksryqtwfan.webp","image_alt":"Illustrated movement cue: March in place. Alternate a comfortable knee lift.","modification":"Keep both hands on a stable chair and lift the feet just a few centimetres.","video_url":null},{"title":"Wall hip hinges","seconds":90,"instruction":"Stand a short step in front of a wall, facing away. Soften knees, push hips back to lightly touch the wall, then stand tall. Keep your back long and pressure through the whole foot.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793751/fitsync/exercises/explore-diagrams/me1sh8gd8g7heyfskvlo.webp","image_alt":"Illustrated movement cue: Hip hinge. Send hips back, keep a long spine.","modification":"Stand closer to the wall and use a shorter range.","video_url":null},{"title":"Small shoulder circles","seconds":60,"instruction":"Stand or sit tall. With arms relaxed, circle the shoulders up, back and down for 30 seconds, then reverse. Keep the neck relaxed; make smooth circles without shrugging hard.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793748/fitsync/exercises/explore-diagrams/khlbksy8mbq6hobq51eg.webp","image_alt":"Illustrated movement cue: Shoulder circles. Small circles, relaxed neck.","modification":"Sit with feet on the floor and reduce the size of each circle.","video_url":null},{"title":"Supported shallow squats","seconds":90,"instruction":"Hold a sturdy support. Place feet about shoulder-width apart. Bend hips and knees together into a comfortable shallow squat, then stand. Keep heels grounded and knees following the toes.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793752/fitsync/exercises/explore-diagrams/xe31ad2yvjy46lnwnh5i.webp","image_alt":"Illustrated movement cue: Supported squat. Sit back with stable support.","modification":"Use a high stable chair for slow sit-to-stands, with arm support as needed.","video_url":null}],"body":[]},{"slug":"standing-desk-reset","title":"Standing desk reset","summary":"A gentle standing break after focused work at your desk.","cover_url":"https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?auto=format&fit=crop&w=1200&q=85","featured_rank":13,"published":true,"kind":"mobility","duration_minutes":5,"tags":["Desk break","Full body"],"steps":[{"title":"Small shoulder circles","seconds":60,"instruction":"Stand or sit tall. With arms relaxed, circle the shoulders up, back and down for 30 seconds, then reverse. Keep the neck relaxed; make smooth circles without shrugging hard.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793748/fitsync/exercises/explore-diagrams/khlbksy8mbq6hobq51eg.webp","image_alt":"Illustrated movement cue: Shoulder circles. Small circles, relaxed neck.","modification":"Sit with feet on the floor and reduce the size of each circle.","video_url":null},{"title":"Standing side reaches","seconds":60,"instruction":"Stand with feet comfortably apart. Reach one arm up, gently lean a little to the opposite side, then return. Alternate sides slowly. Keep breathing; avoid twisting or leaning backward.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793753/fitsync/exercises/explore-diagrams/zm3ecqizcwt4rwtoxuuo.webp","image_alt":"Illustrated movement cue: Side reach. Reach upward without forcing range.","modification":"Sit on a stable chair and reach only as high as comfortable.","video_url":null},{"title":"Supported heel raises","seconds":60,"instruction":"Hold a sturdy chair. Rise onto the balls of both feet, pause briefly and lower slowly. Keep ankles aligned and use the support for balance. Do comfortable reps for the timer.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793754/fitsync/exercises/explore-diagrams/cvd7nilfbmr3myxgjrkf.webp","image_alt":"Illustrated movement cue: Heel raise. Rise slowly, hold a sturdy support.","modification":"Remain seated and raise both heels with the balls of your feet grounded.","video_url":null},{"title":"Easy walking","seconds":120,"instruction":"Walk on a clear, level surface at a relaxed pace. Let breathing settle and arms swing freely. Choose a pace where you can speak easily. The timer is a guide, not a speed target.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793755/fitsync/exercises/explore-diagrams/ytucnrref0j5uxfcf5pr.webp","image_alt":"Illustrated movement cue: Easy walk. A relaxed pace with natural arm swing.","modification":"Walk slowly beside a railing or march seated if standing is uncomfortable.","video_url":null}],"body":[]},{"slug":"chair-movement-break","title":"Chair movement break","summary":"A seated movement break with no floor work. Use a stable chair without wheels.","cover_url":"https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?auto=format&fit=crop&w=1200&q=85","featured_rank":14,"published":true,"kind":"mobility","duration_minutes":4,"tags":["Seated","Beginner"],"steps":[{"title":"Small shoulder circles","seconds":60,"instruction":"Stand or sit tall. With arms relaxed, circle the shoulders up, back and down for 30 seconds, then reverse. Keep the neck relaxed; make smooth circles without shrugging hard.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793748/fitsync/exercises/explore-diagrams/khlbksy8mbq6hobq51eg.webp","image_alt":"Illustrated movement cue: Shoulder circles. Small circles, relaxed neck.","modification":"Sit with feet on the floor and reduce the size of each circle.","video_url":null},{"title":"Seated upper-back turns","seconds":60,"instruction":"Sit toward the front of a stable chair, feet flat. Cross arms over your chest and gently turn your ribs to one side. Return to centre and alternate. Keep knees facing forward.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793749/fitsync/exercises/explore-diagrams/klxkmiaxxjmgepokqvz2.webp","image_alt":"Illustrated movement cue: Seated rotation. Turn the ribs; keep pelvis still.","modification":"Rest hands on thighs and use a smaller turn.","video_url":null},{"title":"Seated forward reach","seconds":60,"instruction":"Sit on a stable chair with feet flat and knees apart. Hinge slightly forward from the hips and reach hands toward your knees. Return upright slowly. Do not round or force your back.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793756/fitsync/exercises/explore-diagrams/whplqood8qodswet9mqv.webp","image_alt":"Illustrated movement cue: Forward reach. Reach hands forward from a chair.","modification":"Keep hands resting on thighs and make the movement smaller.","video_url":null},{"title":"Seated heel raises","seconds":60,"instruction":"Sit tall with both feet flat. Keep the balls of your feet on the floor, lift heels slowly and lower. Repeat gently.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793754/fitsync/exercises/explore-diagrams/cvd7nilfbmr3myxgjrkf.webp","image_alt":"Illustrated movement cue: Heel raise. Rise slowly, hold a sturdy support.","modification":"Lift one heel at a time through a smaller range.","video_url":null}],"body":[]},{"slug":"ankle-and-calf-flow","title":"Ankle & calf flow","summary":"Practice comfortable ankle movement with support for balance.","cover_url":"https://images.unsplash.com/photo-1599901860904-17e6ed7083a0?auto=format&fit=crop&w=1200&q=85","featured_rank":15,"published":true,"kind":"mobility","duration_minutes":5,"tags":["Ankles","Lower body"],"steps":[{"title":"Comfortable marching","seconds":90,"instruction":"Stand tall beside a wall. Lift one foot, set it down softly and alternate. Let your arms move naturally. Start slowly and increase your pace only while breathing comfortably.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793746/fitsync/exercises/explore-diagrams/rglkocnvdlksryqtwfan.webp","image_alt":"Illustrated movement cue: March in place. Alternate a comfortable knee lift.","modification":"Keep both hands on a stable chair and lift the feet just a few centimetres.","video_url":null},{"title":"Supported ankle rocks","seconds":90,"instruction":"Face a wall in a short split stance. Keep the front heel planted and gently move the front knee forward over the toes, then back. Spend 45 seconds on each side without forcing depth.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793750/fitsync/exercises/explore-diagrams/qkksxgcc0ad7vptjzdru.webp","image_alt":"Illustrated movement cue: Ankle rock. Heel stays down, knee moves forward.","modification":"Move the front foot nearer the wall and reduce the forward shift.","video_url":null},{"title":"Supported heel raises","seconds":60,"instruction":"Hold a sturdy chair. Rise onto the balls of both feet, pause briefly and lower slowly. Keep ankles aligned and use the support for balance. Do comfortable reps for the timer.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793754/fitsync/exercises/explore-diagrams/cvd7nilfbmr3myxgjrkf.webp","image_alt":"Illustrated movement cue: Heel raise. Rise slowly, hold a sturdy support.","modification":"Remain seated and raise both heels with the balls of your feet grounded.","video_url":null},{"title":"Gentle wall calf stretch","seconds":60,"instruction":"Hands on a wall, place one leg behind with toes facing forward. Keep the back heel down and knee comfortably straight. Lean forward slightly for a mild stretch. Hold 30 seconds per side without bouncing.","image_url":"https://res.cloudinary.com/qjzkrtfq/image/upload/v1793793757/fitsync/exercises/explore-diagrams/ryqgq4cupcohswhkhwsr.webp","image_alt":"Illustrated movement cue: Calf stretch. Back heel down, both feet forward.","modification":"Use a shorter stance or keep the back knee slightly bent.","video_url":null}],"body":[]},{"slug":"upper-back-movement","title":"Upper-back movement break","summary":"Explore gentle rotation and reachin